mapper.select:
SELECT * FROM (
SELECT ROWNUM AS rnum, A.* FROM (
SELECT user_id as userId, nickname, admin_chk as adminChk
FROM users WHERE 1=1


		 AND user_id LIKE '%' || #{searchWord} || '%' 
		 AND nickname LIKE '%' || #{searchWord} || '%'



ORDER BY user_id ASC
) A WHERE ROWNUM <= #{pageNo} * #{pageSize}
) WHERE rnum > (#{pageNo} - 1) * #{pageSize}

SELECT * FROM (
SELECT ROWNUM AS rnum, A.* FROM (
SELECT diary_sid as diarySid, reg_id as regId, diary_title as diaryTitle,
diary_status as diaryStatus
FROM diary WHERE 1=1


		 AND diary_title LIKE '%' || #{searchWord} || '%'

		 AND reg_id LIKE '%' || #{searchWord} || '%' 


ORDER BY diary_sid DESC
) A WHERE ROWNUM <= #{pageNo} * #{pageSize}
) WHERE rnum > (#{pageNo} - 1) * #{pageSize}
